log.raw:
{
  "understanding": {
    "purpose": "帮助读者按目的地区域和省份查询物流首重、续重费用与预计时效，并比较不同目的地的服务。",
    "reading": "读者先定位地区和省份，再横向读取费用与时效；也可能纵向比较各地的价格和时效。合并的地区单元格将相邻省份归为一组，偏远地区说明则横跨后四列。",
    "groups": [
      "目的地区域和省份共同定位目的地；地区是上一级分组，省份是具体查询项。",
      "首重和续重都是运费，应方便并排比较，同时保留各自的计价单位。",
      "时效与费用共同描述服务结果，但其说明性文字可能比费用数值更长。"
    ],
    "keep_intact": [
      "省份名称及首重、续重的数字。",
      "续重表头中的元/kg单位，以及时效中的数字和时间单位。",
      "地区名称尽量完整显示，以便快速识别行组。"
    ],
    "may_wrap": [
      "较长的时效说明可按语意自然换行。",
      "偏远地区的跨列说明可在地名之间自然换行。",
      "费用表头可在名称与括号单位之间换行；华东、华南的合并地区单元格已有两行数据的高度，可容纳必要的换行。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [98, 52, 67, 89, 53],
      "idea": "优先保持地区名称和两个费用表头完整，适合按目的地查价，但时效说明会较多换行。"
    },
    {
      "name": "B",
      "widths": [76, 52, 67, 89, 75],
      "idea": "在保留费用表头完整的同时增加时效宽度，让地区名称适度换行，平衡查价与阅读时效。"
    },
    {
      "name": "C",
      "widths": [78, 52, 60, 75, 94],
      "idea": "压缩地区和费用表头并允许它们换行，把更多空间留给较长的时效说明，以改善横向阅读。"
    }
  ]
}
